import styled from "styled-components";

export const PropertySiteContainer= styled.div`
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-top: 2rem;
    position: relative;
    

 
    
    
`

export const CardImage= styled.div`
    width:100%;
    height: 50%;
    border-radius:2px;
    object-fit: cover;
  
    img{
        width: 100%;
        height: 100%;
        object-fit: cover;
    }
`
export const PriceContainer= styled.div`
        position: absolute;
        top: 50%;
        left: 30%;
        width: 5rem;
        height:2rem;
        border-radius:30%;
        box-shadow: 4px 10px 10px #F17524 ;
        background: #fc4a1a;  /* fallback for old browsers */
        background: -webkit-linear-gradient(to left, #f7b733, #fc4a1a);  /* Chrome 10-25, Safari 5.1-6 */
        background: linear-gradient(to left, #f7b733, #fc4a1a); /* W3C, IE 10+/ Edge, Firefox 16+, Chrome 26+, Opera 12+, Safari 7+ */
        
        p{
            font-family: "Raleway", sans serif;
        }
`
